[CmdletBinding()]
param([string]$InventoryPath='project-state/master-inventory.json',[string]$ReportPath='project-state/discovery/cabq-404-source-reverification-2026-09-11.json')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$inventoryFull=[IO.Path]::GetFullPath($InventoryPath);$inventory=Get-Content $inventoryFull -Raw -Encoding UTF8|ConvertFrom-Json;$report=Get-Content $ReportPath -Raw -Encoding UTF8|ConvertFrom-Json;$byId=@{};foreach($candidate in $inventory.candidates){$byId[[string]$candidate.id]=$candidate};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach($result in @($report.results)){if([string]$result.status-ne'passed'){throw "Non-passing re-verification result: $($result.url)"};foreach($id in @($result.ids|ForEach-Object{[string]$_})){if(-not$seen.Add($id)){throw "Duplicate re-verification ID: $id"};if(-not$byId.ContainsKey($id)){throw "Missing inventory candidate: $id"};$candidate=$byId[$id];if([string]$candidate.status-ne'requires human review'){throw "Unexpected candidate status: $id = $($candidate.status)"};$note="City HTTP-404 successor re-verification 2026-09-11: $($result.method) confirmed $($result.url) as reachable and suitable ($($result.suitability)).";if(@($candidate.processing_notes)-notcontains$note){$candidate.processing_notes=@($candidate.processing_notes)+@($note)};$candidate.validation_status='requires human review: official City successor or current hub reverified reachable and suitable; completed failed verification result preserved';$candidate.updated_at=(Get-Date).ToUniversalTime().ToString('o')}}
if($seen.Count-ne28){throw "Unexpected re-verification count: $($seen.Count)"};$inventory.generated_at=(Get-Date).ToUniversalTime().ToString('o');$temporary="$inventoryFull.tmp-$PID";try{[IO.File]::WriteAllText($temporary,($inventory|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Move-Item $temporary $inventoryFull -Force}finally{if(Test-Path $temporary){Remove-Item $temporary -Force}};[pscustomobject]@{reverified=$seen.Count;status='requires human review preserved'}|ConvertTo-Json
